let drafts=new Map();try{const saved=JSON.parse(sessionStorage.getItem('yv.marker.drafts.v16')||'[]');if(Array.isArray(saved))drafts=new Map(saved.filter(v=>Array.isArray(v)&&typeof v[0]==='string'&&v[1]&&typeof v[1]==='object'));}catch{}
