function readEditor(form){const fd=new FormData(form),groups=fd.getAll('groups').map(String),purposes=fd.getAll('purposes').map(String);if(groups.length>1&&groups.includes('unassigned'))groups.splice(groups.indexOf('unassigned'),1);return {role:fd.get('mw-role-'+form.dataset.mwEditor),groups:groups.length?groups:['unassigned'],purposes:purposes.length?purposes:['annotation'],userTags:String(fd.get('userTags')||'').split(/[,，;；\n]+/).map(s=>s.trim()).filter(Boolean),rationale:String(fd.get('rationale')||''),evidenceSources:fd.getAll('evidenceSources').map(String)};}
function captureDraft(event){const form=event.target.closest?.('[data-mw-editor]');if(!form||!event.target.name)return;const id=form.dataset.mwEditor;drafts.set(id,{...readEditor(form),_base:drafts.get(id)?._base||JSON.stringify(member(id))});persistDrafts();const note=form.querySelector('.mw-draft-note');if(note)note.hidden=false;}
