const paths={panel:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M8 4v16M12 8h5M12 12h5M12 16h3"/>',tag:'<path d="M3 4h8l10 10-7 7L3 10Z"/><circle cx="7.5" cy="8" r="1"/>',cycle:'<path d="M20 7a9 9 0 1 0 1 8M20 3v5h-5"/><path d="M12 7v5l3 2"/>',source:'<path d="M4 4h6a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H4ZM13 7a3 3 0 0 1 3-3h4v14h-4a3 3 0 0 0-3 3"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 16v5h16v-5"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',edit:'<path d="m15 4 5 5-11 11H4v-5ZM12 7l5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',external:'<path d="M14 3h7v7M21 3 11 13M10 4H4v16h16v-6"/>',shield:'<path d="m12 3 8 3v5c0 5-4 8-8 10-4-2-8-5-8-10V6Z"/><path d="m8 12 3 3 5-6"/>',function:'<circle cx="5" cy="12" r="2"/><circle cx="18" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="m7 11 9-5M7 13l9 5"/>'};
