const data=()=>A().data().markers, records=()=>data().markers, source=id=>A().maps().source.get(id), member=id=>P().markers.find(x=>x.id===id), values=(m,k)=>Array.isArray(m[k])?m[k]:[];
const sourceName=id=>({sgd:'SGD',go_gaf:'Gene Ontology · SGD',go_obo:'GO ontology',sgd_slim:'SGD GO slim',jackson_supp:'Jackson 2020 · Supplement 6'}[id]||String(id).replace(/_/g,' ').replace(/([a-z])(?=20\d\d|19\d\d)/g,'$1 ').replace(/^./,c=>c.toUpperCase()));
