const evidencePhases=e=>[...new Set([...(Array.isArray(e.phases)?e.phases:[]),e.phase,e.tag].filter(p=>PHASES.includes(p)))];
const phaseEvidence=e=>evidencePhases(e).length>0&&(/RNA|scRNA/i.test(e.relation)||e.evidenceLayer?.includes('RNA')||e.grade==='A'||e.grade==='B');
function ensureIndex(){if(indexData===data())return;indexData=data();index=new Map(records().map(m=>[m.id,[m.symbol,m.systematic,m.id,...values(m,'aliases'),...values(m,'tags'),...values(m,'uses'),m.summary,m.summaryEn,...values(m,'go').map(g=>g.id+' '+g.term),...values(m,'evidence').flatMap(e=>[e.tag,e.context,e.relation,e.assay,source(e.sourceId)?.title,e.sourceId])].join(' ').toLowerCase()]));}
const RNA_RELATIONS=new Set(['RNA_peak_in','used_as_scRNA_marker_for','published_expression_signature','source_cluster_marker','member_of_RNA_reference_module','RNA_program_context','scRNA_heterogeneity_example','scRNA_state_association','stable_in_tested_conditions','counterevidence_to_universal_stability','enriched_in_context','induced_in_context','published_bulk_RNA_posttranscriptional_class','published_scrna_coexpression_module','source_differential_RNA','source_named_state_RNA']);
const FUNCTION_RELATIONS=new Set(['GO_slim_function','GO_annotations','curated_function','function_or_state_association','source_functional_set','regulates_process','protein_localization_context']);
const BRANCHES={all:[],rna:['phaseRNA','expressionRNA','singlecellRNA','referenceRNA'],function:['goBP','goMF','goCC','curatedFunction','proteinEvidence'],regulation:['targetProgram','regulatorFunction'],location:['goCC','proteinEvidence','genomicLocation'],population:['populationRNA','noiseEvolution']};
const GO_ASPECT={goBP:'P',goMF:'F',goCC:'C'};
function goRows(m,skip){const aspect=GO_ASPECT[ui.evidenceBranch]||(ui.evidenceKind==='location'?'C':'');return values(m,'go').filter(g=>(!aspect||g.aspect===aspect)&&(skip==='goCodes'||!ui.goCodes.length||ui.goCodes.includes(g.evidenceCode))&&(skip==='goTerms'||!ui.goTerms.length||ui.goTerms.includes(g.id)));}
function branchMatches(m,e){switch(ui.evidenceBranch){case'phaseRNA':return phaseEvidence(e);case'expressionRNA':return RNA_RELATIONS.has(e.relation)&&!phaseEvidence(e);case'singlecellRNA':return /scRNA|source_cluster|published_scrna/.test(e.relation)||e.grade==='A'&&RNA_RELATIONS.has(e.relation);case'referenceRNA':return e.grade==='B'&&RNA_RELATIONS.has(e.relation);case'goBP':case'goMF':case'goCC':return e.relation==='GO_annotations'&&goRows(m).length>0;case'curatedFunction':return ['curated_function','function_or_state_association','source_functional_set','regulates_process'].includes(e.relation);case'proteinEvidence':return e.relation==='protein_localization_context';case'targetProgram':return e.relation==='regulatory_target_set';case'regulatorFunction':return e.relation==='regulates_process';case'genomicLocation':return e.relation==='genomic_context';case'populationRNA':return /^population_/.test(e.relation);case'noiseEvolution':return e.relation==='promoter_noise_evolution_evidence';default:return true;}}
function kindMatches(m,e){switch(ui.evidenceKind){case'rna':return RNA_RELATIONS.has(e.relation);case'function':return FUNCTION_RELATIONS.has(e.relation);case'regulation':return ['regulatory_target_set','regulates_process'].includes(e.relation);case'location':return ['protein_localization_context','genomic_context'].includes(e.relation)||e.relation==='GO_annotations'&&values(m,'go').some(g=>g.aspect==='C');case'population':return /^population_/.test(e.relation)||e.relation==='promoter_noise_evolution_evidence';default:return true;}}
function evidenceMatches(m,skip){return values(m,'evidence').filter(e=>kindMatches(m,e)&&(skip==='goTerms'||skip==='goCodes'?(!GO_ASPECT[ui.evidenceBranch]||e.relation==='GO_annotations')&&goRows(m,skip).length>0:branchMatches(m,e))&&(skip==='phases'||!ui.phases.length||(phaseEvidence(e)&&evidencePhases(e).some(p=>ui.phases.includes(p))))&&(skip==='grades'||!ui.grades.length||ui.grades.includes(e.grade))&&(skip==='sources'||!ui.sources.length||(ui.sources.includes(e.sourceId)||ui.sources.includes(e.extractionSourceId)))&&(!(ui.goTerms.length||ui.goCodes.length)||e.relation==='GO_annotations'&&goRows(m,skip).length>0));}
function measurementMatches(m,skip){return ui.evidenceKind==='all'&&ui.evidenceBranch==='all'&&!ui.phases.length&&!ui.grades.length&&!ui.goTerms.length&&!ui.goCodes.length&&(skip==='sources'||ui.sources.some(id=>values(m,'referenceMeasurements').some(r=>r.sourceId===id)));}
function matches(m,skip){ensureIndex();if(scopeRef!==ui.resultSet){scopeRef=ui.resultSet;scopeIds=new Set(ui.resultSet?.ids||[])}const q=ui.q.trim().toLowerCase();return (!ui.resultSet||scopeIds.has(m.id))&& (!q||index.get(m.id)?.includes(q)||values(m,'tags').some(t=>X(t).toLowerCase().includes(q))||values(m,'uses').some(t=>X(t).toLowerCase().includes(q)))&&(!ui.selectedOnly||selectedIds.has(m.id))&&(!ui.qualification||(m.qualification||'unspecified')===ui.qualification)&&(!ui.use||values(m,'uses').includes(ui.use))&&((skip==='tags'||!ui.tags.length)||(ui.tagMode==='all'?ui.tags.every(t=>values(m,'tags').includes(t)):ui.tags.some(t=>values(m,'tags').includes(t))))&&(skip==='excludedTags'||!ui.excludedTags.some(t=>values(m,'tags').includes(t)))&&(!(ui.phases.length||ui.grades.length||ui.sources.length||ui.evidenceKind!=='all'||ui.evidenceBranch!=='all'||ui.goTerms.length||ui.goCodes.length)||evidenceMatches(m,skip).length>0||measurementMatches(m,skip));}
function resultRows(){selectedIds=new Set(P().markers.map(a=>a.id));return records().filter(m=>matches(m)).sort((a,b)=>(ui.sort==='curated'?Number(!!b.seed)-Number(!!a.seed):ui.sort==='evidenceSort'?values(b,'evidence').length-values(a,'evidence').length:0)||a.symbol.localeCompare(b.symbol));}
function filteredCount(key,value){return records().filter(m=>matches(m,key)&&(key==='tags'||key==='excludedTags'?values(m,'tags').includes(value):evidenceMatches(m,key).some(e=>key==='phases'?phaseEvidence(e)&&evidencePhases(e).includes(value):key==='grades'?e.grade===value:e.sourceId===value||e.extractionSourceId===value)||(key==='sources'&&measurementMatches(m,'sources')&&values(m,'referenceMeasurements').some(r=>r.sourceId===value)))).length;}
function button(action,label,extra='',cls='mw-button'){return `<button type="button" class="${cls}" data-mw="${action}" ${extra}>${label}</button>`;}
function checkbox(key,value,label,count){return `<label class="mw-option"><input type="checkbox" data-mw-filter="${key}" value="${E(value)}" ${ui[key].includes(value)?'checked':''}><span>${E(label)}</span><b>${count}</b></label>`;}
function facet(key,title,body,ic){return `<details class="mw-facet" data-mw-facet="${key}" ${ui.open.has(key)?'open':''}><summary>${icon(ic)}<span>${E(title)}</span><i></i></summary><div class="mw-facet-body">${body}</div></details>`;}
function sourceCoverage(){const unresolved=data().coverage?.unresolvedRows||[];return `<details class="mw-source-coverage"><summary>${icon('source')}<span>${T('sources')} · ${data().sources.length}</span></summary><div class="mw-coverage-grid">${data().sources.map(s=>{const n=records().filter(m=>values(m,'evidence').some(e=>e.sourceId===s.id||e.extractionSourceId===s.id)||values(m,'referenceMeasurements').some(r=>r.sourceId===s.id)).length;return `<div><button data-mw="source-filter" data-value="${E(s.id)}"><span>${E(sourceName(s.id))}<small>${E(s.title)}</small></span><b>${n}</b></button><a href="${E(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="${E(T('readSource')+' · '+sourceName(s.id))}">${icon('external')}</a></div>`;}).join('')}</div>${unresolved.length?`<details class="mw-unresolved-source"><summary>${T('unresolvedSource')} · ${unresolved.length}</summary><p>${T('unresolvedSourceHelp')}</p><div class="mw-stats-table"><table><thead><tr>${['sources','sourceSheet','sourceRow','sourceGene','reason'].map(k=>`<th>${T(k)}</th>`).join('')}</tr></thead><tbody>${unresolved.map(r=>`<tr><td>${E(sourceName(r.source||r.sourceId||''))}</td><td>${E(r.sheet||r.sourceSheet||'')}</td><td>${E(r.row??r.sourceRow??'')}</td><td>${E(r.gene||r.sourceGene||'')}</td><td>${E(r.reason||'')}</td></tr>`).join('')}</tbody></table></div></details>`:''}</details>`;}
function familyMatches(tag){const patterns={familyStress:/应激|稳态|缺氧|氧化|热|渗透|损伤|修复|UPR|Hsf|Msn/i,familyMetabolism:/代谢|营养|碳源|氮源|磷酸|硫|糖|呼吸|发酵|铁|金属|核糖体|翻译|RP|RiBi/i,familyDaughter:/母女|子细胞|形态|年龄|衰老|分离|出芽|极性|黏附|静息/i,familyRegulation:/调控|靶|转录因子|TF|SAGA|Mediator/i,familyFunction:/功能|定位|结构|细胞壁|染色质|染色体|DNA|复制|分泌|骨架|蛋白|囊泡|核苷酸/i};return !patterns[ui.tagFamily]||patterns[ui.tagFamily].test(tag);}
function hierarchyPanel(){return `<div class="mw-hierarchy-kinds">${['all','rna','function','regulation','location','population'].map(k=>button('evidence-kind',`${icon(k==='rna'?'cycle':k==='regulation'?'function':k==='all'?'source':'tag')}<span>${T('kind_'+k)}</span>`,`data-value="${k}" aria-pressed="${ui.evidenceKind===k}"`,'mw-kind-button')).join('')}</div>${BRANCHES[ui.evidenceKind]?.length?`<label class="mw-nested-label"><span>↳ ${T('secondaryFilter')}</span><select data-mw-value="evidenceBranch" aria-label="${T('secondaryFilter')}"><option value="all">${T('allSubtypes')}</option>${BRANCHES[ui.evidenceKind].map(k=>`<option value="${k}" ${ui.evidenceBranch===k?'selected':''}>${T(k)}</option>`).join('')}</select></label>`:''}<p class="mw-family-note">${T('hierarchyHelp')}</p>${GO_ASPECT[ui.evidenceBranch]?goFilters():''}`;}
function goFilters(){const query=ui.goQ.trim().toLowerCase(),counts=new Map(),codes=new Map();for(const m of records()){if(matches(m,'goTerms'))for(const g of goRows(m,'goTerms')){const entry=counts.get(g.id)||{id:g.id,term:g.term,genes:new Set()};entry.genes.add(m.id);counts.set(g.id,entry)}if(matches(m,'goCodes'))for(const g of goRows(m,'goCodes')){if(!codes.has(g.evidenceCode))codes.set(g.evidenceCode,new Set());codes.get(g.evidenceCode).add(m.id)}}const terms=[...counts.values()].filter(g=>!query||`${g.id} ${g.term}`.toLowerCase().includes(query)).sort((a,b)=>Number(ui.goTerms.includes(b.id))-Number(ui.goTerms.includes(a.id))||b.genes.size-a.genes.size||a.id.localeCompare(b.id)),pages=Math.max(1,Math.ceil(terms.length/20));ui.goPage=Math.min(ui.goPage,pages);return `<div class="mw-go-subfilters"><p>${T('goFilterHelp')}</p><label class="mw-small-search">${icon('search')}<input id="mw-go-query" type="search" value="${E(ui.goQ)}" placeholder="${T('goSearch')}" aria-label="${T('goSearch')}"></label><div class="mw-go-term-list">${terms.slice((ui.goPage-1)*20,ui.goPage*20).map(g=>checkbox('goTerms',g.id,g.id+' · '+g.term,g.genes.size)).join('')||`<p>${T('noResults')}</p>`}</div><div class="mw-go-pages">${button('go-page','←',`data-value="${ui.goPage-1}" aria-label="${T('previous')}" ${ui.goPage<=1?'disabled':''}`,'mw-icon-button')}<span>${ui.goPage} / ${pages} · ${terms.length} ${T('goTermsLabel')}</span>${button('go-page','→',`data-value="${ui.goPage+1}" aria-label="${T('next')}" ${ui.goPage>=pages?'disabled':''}`,'mw-icon-button')}</div><details class="mw-go-codes"><summary>${T('goEvidenceCodes')}</summary>${[...codes].sort().map(([code,genes])=>checkbox('goCodes',code,code,genes.size)).join('')}<p>${T('goCodeHelp')}</p></details></div>`;}
function phaseCoverage(){const phaseGenes=new Set(),sourceRows=new Map();for(const m of records())for(const e of values(m,'evidence'))if(phaseEvidence(e)){phaseGenes.add(m.id);if(!sourceRows.has(e.sourceId))sourceRows.set(e.sourceId,new Map(PHASES.map(p=>[p,new Set()])));evidencePhases(e).forEach(phase=>sourceRows.get(e.sourceId).get(phase).add(m.id))}return `<details class="mw-phase-coverage"><summary>${T('phaseCoverage')}</summary><p>${T('phaseGranularity')}</p><div class="mw-phase-coverage-table"><table><thead><tr><th>${T('sources')}</th>${PHASES.map(p=>`<th>${p}</th>`).join('')}</tr></thead><tbody>${[...sourceRows].map(([id,counts])=>`<tr><th><a href="${E(source(id)?.url||'#')}" target="_blank" rel="noopener noreferrer">${E(sourceName(id))}</a></th>${PHASES.map(p=>`<td><button data-mw="phase-source" data-value="${p}" data-source="${E(id)}" ${counts.get(p).size?'':'disabled'}>${counts.get(p).size}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><p>${T('noPhaseEvidence')} <b>${records().length-phaseGenes.size}</b> / ${records().length}. ${T('phaseCountsHelp')}</p></details>`;}
function tagChoice(tag){return `<div class="mw-tag-choice ${ui.excludedTags.includes(tag)?'is-excluded':''}">${checkbox('tags',tag,X(tag),filteredCount('tags',tag))}${button('exclude-tag',icon('minus'),`data-value="${E(tag)}" aria-label="${E(T('excludeTag')+' · '+X(tag))}" title="${E(T('excludeTag')+' · '+X(tag))}" aria-pressed="${ui.excludedTags.includes(tag)}"`,'mw-tag-exclude')}</div>`;}
function filterPanel(){const scopedTags=new Set(records().flatMap(m=>ui.evidenceKind==='all'&&ui.evidenceBranch==='all'?values(m,'tags'):values(m,'evidence').filter(e=>kindMatches(m,e)&&branchMatches(m,e)).map(e=>e.tag))),tagQ=ui.tagQ.trim().toLowerCase(),tags=[...scopedTags].filter(t=>familyMatches(t)&&(!tagQ||[t,X(t)].join(' ').toLowerCase().includes(tagQ))).sort((a,b)=>Number(ui.tags.includes(b)||ui.excludedTags.includes(b))-Number(ui.tags.includes(a)||ui.excludedTags.includes(a))||X(a).localeCompare(X(b)));const uses=[...new Set(records().flatMap(m=>values(m,'uses')))];return `<aside id="mw-filter-panel" class="mw-filters" aria-label="${T('filter')}"><div class="mw-filter-title"><strong>${icon('filter')}${T('filter')}</strong>${button('reset',T('reset'),'','mw-text-button')}</div>${facet('hierarchy',T('evidenceHierarchy'),hierarchyPanel(),'source')}${facet('identity',T('featureQualification'),`<label class="mw-select-label">${T('referenceClass')}<select data-mw-value="qualification" aria-label="${T('referenceClass')}">${['','Verified','Uncharacterized','Dubious','unspecified'].map(q=>`<option value="${q}" ${ui.qualification===q?'selected':''}>${q?T('orf'+q):T('all')}</option>`).join('')}</select></label><p class="mw-filter-rule">${T('qualificationBoundary')}</p>`,'shield')}<p class="mw-filter-rule">${T('tagRule')}</p>${ui.evidenceKind==='all'||ui.evidenceKind==='rna'?facet('phase',T('phase'),PHASES.map(p=>checkbox('phases',p,p,filteredCount('phases',p))).join(''),'cycle'):''}${facet('tags',T('tags'),`<div class="mw-segment">${['all','any'].map(v=>button('tag-mode',U(v==='all'?'allTags':'anyTag'),`data-value="${v}" aria-pressed="${ui.tagMode===v}"`)).join('')}</div><p class="mw-family-note">${T('tagAlgebraHelp')}</p><label class="mw-family-select">${T('tagFamily')}<select data-mw-value="tagFamily" aria-label="${T('tagFamily')}">${['familyAll','familyStress','familyMetabolism','familyDaughter','familyRegulation','familyFunction'].map(k=>`<option value="${k}" ${ui.tagFamily===k?'selected':''}>${T(k)}</option>`).join('')}</select></label><label class="mw-small-search">${icon('search')}<input id="mw-tag-query" type="search" value="${E(ui.tagQ)}" placeholder="${T('tagSearch')}" aria-label="${T('tagSearch')}"></label><div class="mw-tag-options">${tags.map(tagChoice).join('')||`<p>${T('noTagsInBranch')}</p>`}</div>`,'tag')}${facet('grade',T('grade'),['A','B','C','D'].map(g=>checkbox('grades',g,g+' · '+A().t(g.toLowerCase()+'Title'),filteredCount('grades',g))).join(''),'shield')}${facet('sources',T('sources'),data().sources.map(s=>checkbox('sources',s.id,sourceName(s.id),filteredCount('sources',s.id))).join(''),'source')}<label class="mw-select-label">${T('annotationUse')}<select data-mw-value="use" aria-label="${T('annotationUse')}"><option value="">${T('all')}</option>${uses.map(u=>`<option value="${E(u)}" ${ui.use===u?'selected':''}>${E(X(u))}</option>`).join('')}</select></label><p class="mw-count-note">${T('facetCountHelp')}</p>${button('mobile-filters',U('hideFilters'),'','mw-button mw-filter-done')}</aside>`;}
function classification(e){return e?.grade==='A'?'annotationRNA':e?.grade==='B'?'referenceRNA':e?.grade==='C'?'functional':'candidate';}
// Preview order is a navigation choice, never an evidence grade or confidence score.
function previewTags(m){const relationGroups=[new Set(['RNA_peak_in','used_as_scRNA_marker_for','published_expression_signature','source_cluster_marker','member_of_RNA_reference_module','RNA_program_context','scRNA_heterogeneity_example','scRNA_state_association','population_RNA_association','population_RNA_protein_association','stable_in_tested_conditions','counterevidence_to_universal_stability','enriched_in_context','induced_in_context','published_bulk_RNA_posttranscriptional_class','published_scrna_coexpression_module','promoter_noise_evolution_evidence','source_differential_RNA','source_named_state_RNA']),new Set(['regulatory_target_set']),new Set(['regulates_process','function_or_state_association','source_functional_set']),new Set(['GO_slim_function']),new Set(['protein_localization_context','genomic_context'])];const generic=new Set(['核心整理种子','SGD功能注释','GO功能注释','周期候选']);const order=tag=>{if(generic.has(tag))return 9;const es=values(m,'evidence').filter(e=>e.tag===tag);const found=relationGroups.findIndex(group=>es.some(e=>group.has(e.relation)));return found<0?6:found;};return values(m,'tags').map((tag,i)=>({tag,i,order:order(tag)})).sort((a,b)=>a.order-b.order||a.i-b.i).map(x=>x.tag);}
function evidenceTags(m,limit){const tags=values(m,'tags'),rows=limit?tags.slice(0,limit):tags;return `<div class="mw-evidence-tags">${rows.map(tag=>{const es=values(m,'evidence').filter(e=>e.tag===tag),grades=[...new Set(es.map(e=>e.grade))].sort(),label=grades.length?grades.join('/'):'·';return `<button type="button" class="mw-evidence-tag ${es.length?'has-evidence':'catalogue-tag'}" data-mw="evidence" data-id="${E(m.id)}" data-tag="${E(tag)}" title="${E(T('evidenceTitle')+' · '+X(tag))}"><span>${E(X(tag))}</span><b>${label}</b>${icon('external')}</button>`;}).join('')}</div>`;}
function goPreview(m){if(!GO_ASPECT[ui.evidenceBranch])return '';const gs=[...new Map(goRows(m).map(g=>[g.id,g])).values()];return `<div class="mw-go-preview"><span>${T('matchingGO')}</span>${gs.slice(0,3).map(g=>button('go-evidence',`${E(g.term)} <small>${E(g.id)}</small>`,`data-id="${E(m.id)}" data-go="${E(g.id)}"`,'mw-go-preview-tag')).join('')}${gs.length>3?`<small>+ ${gs.length-3}</small>`:''}</div>`;}
function card(m){const selected=!!member(m.id),es=evidenceMatches(m),active=ui.phases.length||ui.grades.length||ui.sources.length||ui.evidenceKind!=='all'||ui.evidenceBranch!=='all',shown=active?[...new Set(es.map(e=>e.tag))]:previewTags(m).slice(0,5);const display={...m,tags:shown};return `<article class="mw-marker-card ${selected?'is-selected':''}" data-mw-record="${E(m.id)}"><div class="mw-card-heading"><button type="button" class="mw-select-gene" data-mw="select" data-id="${E(m.id)}" aria-pressed="${selected}" aria-label="${E(T(selected?'remove':'add')+' · '+m.symbol)}">${icon(selected?'check':'plus')}</button><div><button class="mw-gene-name" type="button" data-action="open" data-kind="marker" data-id="${E(m.id)}">${E(m.symbol)}</button><span class="mw-gene-id">${E(m.systematic||m.id)}</span></div><span class="mw-record-kind">${E(X(m.category||T('generic')))}</span></div><div class="mw-phase-row"><span>${T('sourcePhase')}</span><strong>${values(m,'phases').join(' · ')||'—'}</strong></div>${active?`<small class="mw-match-label">${T('matching')} · ${es.length}</small>`:''}${evidenceTags(display,active?6:5)}${goPreview(m)}${values(m,'tags').length>shown.length?button('all-tags',T('moreTags')+` <b>${values(m,'tags').length}</b>`,`data-id="${E(m.id)}"`,'mw-text-button'):''}${m.referenceMeasurements?.length?button('reference-stats',T('referenceMeasurements')+` · ${m.referenceMeasurements.length}`,`data-id="${E(m.id)}"`,'mw-text-button'):''}<div class="mw-card-foot"><span>${values(m,'evidence').length} ${T('relationships')}</span><button type="button" data-mw="edit" data-id="${E(m.id)}">${T(selected?'edit':'add')}${icon('arrow')}</button></div></article>`;}
function activeFilters(){const chips=[['phases',ui.phases],['grades',ui.grades],['sources',ui.sources],['tags',ui.tags],['excludedTags',ui.excludedTags],['goTerms',ui.goTerms],['goCodes',ui.goCodes]].flatMap(([key,items])=>items.map(value=>{const label=(key==='excludedTags'?T('excludedPrefix')+' ':'')+(key==='sources'?sourceName(value):X(value));return button('remove-filter',`${E(label)}${icon('close')}`,`data-key="${key}" data-value="${E(value)}" aria-label="${E(U('removeFilter')+' · '+label)}"`,'mw-active-filter'+(key==='excludedTags'?' mw-excluded-filter':''))}));for(const [key,label] of [['q',ui.q.trim()?U('searchTerm')+': '+ui.q:''],['qualification',ui.qualification?T('referenceClass')+': '+T('orf'+ui.qualification):''],['use',ui.use?T('annotationUse')+': '+X(ui.use):''],['selectedOnly',ui.selectedOnly?T('hasPlan'):'']])if(label)chips.push(button('clear-filter',`${E(label)}${icon('close')}`,`data-key="${key}" aria-label="${E(U('removeFilter')+' · '+label)}"`,'mw-active-filter'));if(ui.evidenceKind!=='all')chips.unshift(button('evidence-kind',`${T('kind_'+ui.evidenceKind)}${ui.evidenceBranch!=='all'?' / '+T(ui.evidenceBranch):''}${icon('close')}`,`data-value="all" aria-label="${E(U('removeFilter')+' · '+T('kind_'+ui.evidenceKind))}"`,'mw-active-filter'));if(ui.resultSet)chips.push(button('clear-scope',`${E(ui.resultSet.label)}${icon('close')}`,`aria-label="${E(U('removeFilter')+' · '+ui.resultSet.label)}"`,'mw-active-filter'));return chips.join('');}
function filterTotal(){return ui.phases.length+ui.grades.length+ui.sources.length+ui.tags.length+ui.excludedTags.length+ui.goTerms.length+ui.goCodes.length+(ui.use?1:0)+(ui.qualification?1:0)+(ui.evidenceKind==='all'?0:1)+(ui.q.trim()?1:0)+(ui.selectedOnly?1:0)+(ui.resultSet?1:0);}
function selectedSummary(rows){const chosen=P().markers;if(!chosen.length)return '';const resultIds=new Set(rows.map(m=>m.id)),outside=chosen.filter(a=>!resultIds.has(a.id)).length;return `<section class="mw-chosen-summary" aria-label="${U('chosen')}"><div class="mw-chosen-heading"><span>${icon('check')}<strong>${chosen.length}</strong> ${U('chosen')}</span>${button('review-selected',`${U('reviewChosen')}${icon('arrow')}`,'','mw-text-button')}</div><div class="mw-chosen-genes">${chosen.slice(0,8).map(a=>{const m=A().maps().marker.get(a.id);if(!m)return '';return `<div class="mw-chosen-gene ${resultIds.has(a.id)?'':'outside-filter'}"><button data-action="open" data-kind="marker" data-id="${E(a.id)}" aria-label="${E(U('viewMarker')+' · '+m.symbol)}">${E(m.symbol)}</button>${button('remove',icon('close'),`data-id="${E(a.id)}" aria-label="${E(T('remove')+' · '+m.symbol)}"`,'mw-chosen-remove')}</div>`}).join('')}${chosen.length>8?button('review-selected','+ '+(chosen.length-8),'','mw-chosen-more'):''}</div>${outside?`<p class="mw-chosen-outside"><b>${outside}</b> ${U('outside')}</p>`:''}</section>`;}
function resetFilters(keepQuery=false){Object.assign(ui,{q:keepQuery?ui.q:'',phases:[],grades:[],sources:[],tags:[],excludedTags:[],qualification:'',use:'',tagQ:'',tagFamily:'familyAll',evidenceKind:'all',evidenceBranch:'all',goTerms:[],goCodes:[],goQ:'',goPage:1,page:1,selectedOnly:false,resultSet:null});}
function filterSnapshot(){const keys=['q','phases','grades','sources','tags','excludedTags','qualification','use','tagMode','evidenceKind','evidenceBranch','goTerms','goCodes','selectedOnly'];return Object.fromEntries(keys.map(k=>[k,Array.isArray(ui[k])?[...ui[k]]:ui[k]]));}
function setAlgebra(rows){const a=ui.setA?.ids||[],b=rows.map(m=>m.id),sa=new Set(a),sb=new Set(b),intersection=a.filter(id=>sb.has(id)).length,union=new Set([...a,...b]).size,difference=a.filter(id=>!sb.has(id)).length;return `<details class="mw-set-algebra" ${ui.setA?'open':''}><summary>${icon('function')}${T('compareSets')}${ui.resultSet?`<b>${E(ui.resultSet.label)}</b>`:''}</summary><p>${T('setHelp')}</p><div class="mw-set-inputs"><div><span>A · ${T('savedSet')}</span><strong>${ui.setA?a.length:'—'}</strong>${button('capture-set',T(ui.setA?'replaceSet':'saveSet'),'','mw-text-button')}</div><div><span>B · ${T('currentSet')}</span><strong>${b.length}</strong><small>${T('setCurrentHelp')}</small></div></div>${ui.setA?`<div class="mw-set-operations">${[['union','A ∪ B',union],['intersection','A ∩ B',intersection],['difference','A − B',difference]].map(([op,label,count])=>button('combine-set',`${label}<b>${count}</b>`,`data-value="${op}" title="${E(U(op==='union'?'setUnion':op==='intersection'?'setIntersection':'setDifference'))}" aria-label="${E(label+' · '+U(op==='union'?'setUnion':op==='intersection'?'setIntersection':'setDifference')+' · '+count)}"`,'mw-set-operation')).join('')}${button('clear-set',T('clearSet'),'','mw-text-button')}</div>`:''}${ui.resultSet?`<p class="mw-set-scope">${T('currentScope')} <b>${E(ui.resultSet.label)} · ${ui.resultSet.ids.length}</b> ${button('clear-scope',T('clearScope'),'','mw-text-button')}</p>`:''}</details>`;}
function combineSet(op){if(!ui.setA)return;const a=ui.setA.ids,b=resultRows().map(m=>m.id),sb=new Set(b),queryB=filterSnapshot(),queryA=ui.setA.filters,ids=op==='union'?[...new Set([...a,...b])]:op==='intersection'?a.filter(id=>sb.has(id)):a.filter(id=>!sb.has(id)),label=op==='union'?'A ∪ B':op==='intersection'?'A ∩ B':'A − B';resetFilters();ui.resultSet={ids,label,queryA,queryB};refresh();}
function pager(current,total,action){return `<nav class="mw-pagination" aria-label="${T('page')}">${button(action,`← ${T('previous')}`,`data-value="${current-1}" ${current<=1?'disabled':''}`)}<span>${T('page')} ${current} / ${Math.max(1,total)}</span>${button(action,`${T('next')} →`,`data-value="${current+1}" ${current>=total?'disabled':''}`)}</nav>`;}
function catalogue(){const rows=resultRows(),pages=Math.ceil(rows.length/ui.size);ui.page=Math.min(ui.page,Math.max(1,pages));const sliced=rows.slice((ui.page-1)*ui.size,ui.page*ui.size),selected=P().markers;return `${selectedSummary(rows)}<div class="mw-search-toolbar mw-catalogue-search"><label class="mw-search">${icon('search')}<input id="mw-query" type="search" value="${E(ui.q)}" placeholder="${T('search')}" aria-label="${T('search')}"></label><select data-mw-value="sort" aria-label="${T('sort')}">${['curated','alphabet','evidenceSort'].map(s=>`<option value="${s}" ${ui.sort===s?'selected':''}>${T(s)}</option>`).join('')}</select></div><div class="mw-catalogue ${ui.mobileFilters?'filters-open':''}">${button('mobile-filters',`${icon('filter')}${T('filter')} <b>${filterTotal()}</b>`,`aria-expanded="${ui.mobileFilters}" aria-controls="mw-filter-panel"`,'mw-button mw-mobile-filter-toggle')}${filterPanel()}<section class="mw-results"><div class="mw-active-filters">${activeFilters()}${filterTotal()?button('reset',U('resetSearch'),'','mw-clear-filters'):''}</div><details class="mw-filter-explainer"><summary>${U('filterLogic')}</summary><p>${U('filterHelp')}</p></details><div class="mw-result-summary"><strong role="status" aria-live="polite" aria-atomic="true">${rows.length} <span>${T('results')}</span></strong><label class="mw-option mw-selected-switch"><input type="checkbox" data-mw-selected-only ${ui.selectedOnly?'checked':''}><span>${T('hasPlan')}</span></label>${button('add-page',`${icon('plus')}${T('addPage')}`,`${rows.length?'':'disabled'}`)}</div>${setAlgebra(rows)}${rows.length?`<div class="mw-marker-grid">${sliced.map(card).join('')}</div>`:`<div class="mw-empty">${icon('filter')}<h2>${T('noResults')}</h2>${button('reset',T('reset'))}${ui.q?button('search-all',T('searchAll')):''}</div>`}${pager(ui.page,pages,'page')}${selected.length?`<div class="mw-selection-tray"><span>${icon('panel')}<strong>${selected.length}</strong>${T('selected')}</span><div>${button('tab',T('panel'),`data-value="panel"`,'mw-button mw-primary')}<a class="mw-button" href="#builder?tab=studio">${T('plan')}${icon('arrow')}</a></div></div>`:''}</section></div>`;}
function assignmentText(a){return [T('role')+': '+T(a.role||'include'),T('purposes')+': '+(a.purposes||[a.purpose||'annotation']).map(T).join(', '),T('plannedPhase')+': '+(a.groups||['unassigned']).map(g=>PHASES.includes(g)?g:T(g)).join(', '),a.userTags?.length?T('customTags')+': '+a.userTags.join(', '):'',a.evidenceSources?.length?T('reviewedSources')+': '+a.evidenceSources.map(sourceName).join(', '):'',a.rationale?T('rationale')+': '+a.rationale:''].filter(Boolean).join('; ');}
function assignmentHTML(a){return `<dl class="mw-assignment"><dt>${T('role')}</dt><dd>${E(T(a.role||'include'))}</dd><dt>${T('purposes')}</dt><dd>${(a.purposes||[a.purpose||'annotation']).map(v=>E(T(v))).join(' · ')}</dd><dt>${T('groups')}</dt><dd>${(a.groups||['unassigned']).map(v=>E(PHASES.includes(v)?v:T(v))).join(' · ')}</dd>${a.userTags?.length?`<dt>${T('customTags')}</dt><dd>${a.userTags.map(E).join(' · ')}</dd>`:''}${a.evidenceSources?.length?`<dt>${T('reviewedSources')}</dt><dd>${a.evidenceSources.map(s=>E(sourceName(s))).join(' · ')}</dd>`:''}${a.rationale?`<dt>${T('rationale')}</dt><dd>${E(a.rationale)}</dd>`:''}</dl>`;}
function review(p=P()){const active=p.markers.filter(a=>a.role!=='exclude');return {notReviewed:active.filter(a=>!a.evidenceSources?.length).map(a=>a.id),unassigned:active.filter(a=>!a.groups?.length||a.groups.includes('unassigned')).map(a=>a.id),noRationale:p.markers.filter(a=>['exclude','control'].includes(a.role)&&!a.rationale?.trim()).map(a=>a.id),leakage:active.filter(a=>(a.purposes||[]).includes('annotation')&&(a.purposes||[]).includes('validationUse')).map(a=>a.id),unsupportedGroup:active.filter(a=>a.groups?.some(g=>PHASES.includes(g)&&!values(A().maps().marker.get(a.id)||{},'evidence').some(e=>phaseEvidence(e)&&evidencePhases(e).includes(g)&&(a.evidenceSources||[]).includes(e.sourceId)))).map(a=>a.id)};}
function reviewPanel(p=P()){if(!p.markers.length)return '';const warnings=Object.entries(review(p)).filter(([,ids])=>ids.length);return `<details class="mw-review"><summary>${icon('shield')}<strong>${T('review')}</strong><span>${warnings.length}</span></summary><p>${T('reviewHelp')}</p>${warnings.map(([key,ids])=>`<div class="mw-review-item"><span>${E(T(key))}</span><b>${ids.length}</b><small>${ids.slice(0,12).map(id=>E(A().maps().marker.get(id)?.symbol||id)).join(', ')}${ids.length>12?' …':''}</small></div>`).join('')}</details>`;}
