function importPage(){const r=ui.resolved;return `<section class="mw-import"><div><h2>${T('importTab')}</h2><p>${T('importHelp')}</p></div><div class="mw-import-grid"><div><label class="mw-field"><span>${T('paste')}</span><textarea id="mw-import-text" rows="12" placeholder="CLN2&#10;YLR131C&#10;S000004121">${E(ui.importText)}</textarea></label><div class="mw-import-actions"><label class="mw-button">${icon('upload')}${T('chooseFile')}<input type="file" id="mw-import-file" accept=".json,.txt,.tsv,.csv" class="mw-file-input"></label>${button('resolve',T('resolve'),'','mw-button mw-primary')}</div><p class="mw-import-boundary">${T('importBoundary')}</p></div><div class="mw-import-preview">${r?`<div class="mw-import-counts">${[['matched',r.rows.length],['unresolved',r.unresolved.length],['duplicate',r.duplicate]].map(([k,n])=>`<div><b>${n}</b><span>${T(k)}</span></div>`).join('')}</div><div class="mw-import-matches">${r.rows.slice(0,80).map(a=>{const m=A().maps().marker.get(a.id);return `<span>${E(m.symbol)}<small>${E(m.systematic)}</small></span>`}).join('')}${r.rows.length>80?`<span>+ ${r.rows.length-80}</span>`:''}</div>${r.unresolved.length?`<details open><summary>${T('unresolved')} · ${r.unresolved.length}</summary><p>${r.unresolved.slice(0,100).map(E).join(' · ')}</p></details>`:''}${button('apply-import',`${icon('plus')}${T('applyImport')}`,r.rows.length?'':'disabled','mw-button mw-primary')}`:`<div class="mw-empty">${icon('upload')}<p>${T('importHelp')}</p></div>`}</div></div></section>`;}
function page(){if(lastRouteHash!==location.hash){lastRouteHash=location.hash;const v=new URLSearchParams(location.hash.split('?')[1]||'').get('view');if(['catalogue','panel','preview','importTab','coverage'].includes(v))ui.tab=v;}ensureIndex();selectedIds=new Set(P().markers.map(a=>a.id));const chosen=selectedIds.size,es=records().reduce((n,m)=>n+values(m,'evidence').length,0);return `<div class="mw-workspace"><div class="mw-heading"><div><span class="eyebrow">YEASTVAR1011 / ${T('catalogue')}</span><h1>${T('title')}</h1><p>${T('lead')}</p></div><a href="#workflow?step=markers" class="mw-method-link">${T('annotationUse')}${icon('arrow')}</a></div><div class="mw-statline">${[['genes',records().length],['relationships',es],['sources',data().sources.length],['selected',chosen]].map(([key,n])=>`<div><strong>${n.toLocaleString()}</strong><span>${T(key)}</span></div>`).join('')}</div><nav class="mw-tabs" aria-label="${T('title')}">${[['catalogue','source'],['panel','panel'],['preview','function'],['coverage','shield'],['importTab','upload']].map(([tab,ic])=>button('tab',`${icon(ic)}${T(tab)}${tab==='panel'?`<b>${chosen}</b>`:''}`,`data-value="${tab}" aria-current="${ui.tab===tab?'page':'false'}"`,ui.tab===tab?'mw-tab active':'mw-tab')).join('')}</nav>${ui.tab==='catalogue'?(window.YV_RESEARCH_ATLAS.markerUpdate()+catalogue()):ui.tab==='panel'?panel():ui.tab==='preview'?window.YV_MARKER_PREVIEW.page():ui.tab==='coverage'?window.YV_RESEARCH_ATLAS.coverage():importPage()}<section class="mw-measurement-note">${icon('function')}<div><strong>${T('unmeasured')}</strong><p>${T('measureHelp')}</p><div>${['mean','detection','rank','specificity'].map(k=>`<span>${T(k)} <b>${T('pending')}</b></span>`).join('')}</div></div></section>${phaseCoverage()}${sourceCoverage()}</div>`;}
function refresh(focusId){const active=focusId?document.getElementById(focusId):document.activeElement,position=active?.selectionStart,end=active?.selectionEnd,scroll=window.scrollY,attributes=['data-mw','data-id','data-value','data-key','data-mw-filter','data-mw-value','data-mw-selected-only','data-mw-checked','value'],selector=active?.id?'#'+CSS.escape(active.id):active?.closest('.mw-workspace')?attributes.filter(k=>active.hasAttribute(k)).map(k=>'['+k+'="'+CSS.escape(active.getAttribute(k))+'"]' ).join(''):'',inner=['.mw-filters','.mw-tag-options','.mw-go-term-list',...Array.from(document.querySelectorAll('.mw-facet'),el=>'[data-mw-facet="'+CSS.escape(el.dataset.mwFacet)+'"] .mw-facet-body')].map(sel=>[sel,document.querySelector(sel)?.scrollTop||0]);A().render();for(const [sel,top] of inner){const el=document.querySelector(sel);if(el)el.scrollTop=top;}if(selector){const el=document.querySelector(selector)||(active?.dataset.mw==='select'?document.querySelector('.mw-select-gene'):active?.dataset.mw==='remove'?document.querySelector('.mw-chosen-remove'):null)||document.getElementById('mw-query')||document.getElementById('mw-panel-query');el?.focus({preventScroll:true});try{el?.setSelectionRange(position,end)}catch{}}window.scrollTo(0,scroll);}
function dialogClose(){if(!dialog)return;dialog.close();dialog.remove();dialog=null;if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
function showDialog(html){dialogClose();returnFocus=document.activeElement;dialog=document.createElement('dialog');dialog.className='mw-evidence-dialog';dialog.setAttribute('aria-labelledby','mw-dialog-title');dialog.innerHTML=`<div class="mw-dialog-shell"><div class="mw-dialog-top"><span>${T('evidenceTitle')}</span>${button('close-dialog',icon('close'),`aria-label="${T('close')}"`,'mw-icon-button')}</div>${html}</div>`;document.body.append(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();dialogClose()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialogClose()});dialog.showModal();}
function sourceStatistics(e){const stats=Object.entries(e.referenceStatistics||{}),meanings={avg_log2FC:'meanLogFC','pct.1':'detectGroup1','pct.2':'detectGroup2',p_val_adj:'adjustedP'};if(!stats.length&&!e.sourceSheet&&!e.sourceRow)return window.YV_MARKER_PREVIEW?.sourceMetadata(e)||'';return `<details class="mw-source-statistics"><summary>${T('sourceStatistics')}</summary><p>${T('sourceStatsBoundary')}</p>${window.YV_MARKER_PREVIEW?.sourceMetadata(e)||''}<dl>${[['sourceSheet',e.sourceSheet],['sourceRow',e.sourceRow],['sourceGene',e.sourceGene]].filter(([,v])=>v!==undefined&&v!==null).map(([key,v])=>`<dt>${T(key)}</dt><dd>${E(v)}</dd>`).join('')}</dl>${stats.length?`<div class="mw-stats-table"><table><thead><tr><th>${T('statField')}</th><th>${T('statValue')}</th><th>${T('statMeaning')}</th></tr></thead><tbody>${stats.map(([key,value])=>`<tr><td><code>${E(key)}</code></td><td>${E(value===null||value===undefined?'—':typeof value==='object'?JSON.stringify(value):value)}</td><td>${E(meanings[key]?T(meanings[key]):key)}</td></tr>`).join('')}</tbody></table></div>`:''}</details>`;}
function showEvidence(id,tag){const m=A().maps().marker.get(id);if(!m)return;const es=values(m,'evidence').filter(e=>e.tag===tag);showDialog(`<h2 id="mw-dialog-title">${E(m.symbol)} <span>/ ${E(X(tag))}</span></h2><p class="mw-dialog-boundary">${T('functionalBoundary')}</p>${es.length?es.map(e=>`<article class="mw-evidence-relation"><div class="mw-relation-heading"><span class="mw-evidence-grade grade-${E(e.grade)}">${E(e.grade)}</span><strong>${T(classification(e))}</strong></div><dl><dt>${T('relation')}</dt><dd><code>${E(e.relation)}</code></dd><dt>${T('context')}</dt><dd>${E(X(e.context))}</dd><dt>${T('assay')}</dt><dd>${E(X(e.assay))}</dd><dt>${T('limit')}</dt><dd>${E(X(e.limitation))}</dd></dl><div class="mw-reference-links"><a href="${E(e.sourceUrl||source(e.sourceId)?.url||'#')}" target="_blank" rel="noopener noreferrer">${icon('source')}${E(sourceName(e.sourceId))}${icon('external')}</a>${e.extractionSourceId&&e.extractionSourceId!==e.sourceId&&source(e.extractionSourceId)?`<a href="${E(source(e.extractionSourceId).url)}" target="_blank" rel="noopener noreferrer">${E(sourceName(e.extractionSourceId))}${icon('external')}</a>`:''}</div>${sourceStatistics(e)}</article>`).join(''):`<div class="mw-empty-evidence">${T('noTagEvidence')}</div>`}${tag==='GO功能注释'||es.some(e=>e.relation==='GO_slim_function')?`<details class="mw-go-evidence"><summary>${T('allGeneGO')} (${values(m,'go').length})</summary><div>${values(m,'go').map(g=>`<a href="https://amigo.geneontology.org/amigo/term/${encodeURIComponent(g.id)}" target="_blank" rel="noopener noreferrer"><span>${E(g.id)} · ${E(g.term)}</span><b>${E(g.evidenceCode)}</b></a>`).join('')}</div></details>`:''}<div class="mw-dialog-actions">${button('edit',`${icon('plus')}${T('edit')}`,`data-id="${E(id)}"`,'mw-button mw-primary')}${button('full-record',T('details'),`data-id="${E(id)}"`)}</div>`);}
function showReferenceMeasurements(id){const m=A().maps().marker.get(id);if(!m)return;showDialog(`<h2 id="mw-dialog-title">${E(m.symbol)} / ${T('referenceMeasurements')}</h2><p class="mw-dialog-boundary">${T('sourceStatsBoundary')}</p>${(m.referenceMeasurements||[]).map(r=>`<article class="mw-evidence-relation"><strong>${E(r.sourceSheet)}</strong><p>${E(X(r.note||''))}</p>${sourceStatistics({...r,referenceStatistics:r.statistics})}<div class="mw-reference-links"><a href="${E(source(r.sourceId)?.url||'#')}" target="_blank" rel="noopener noreferrer">${E(sourceName(r.sourceId))} ↗</a></div></article>`).join('')}`);}
function referenceUrl(ref){if(ref.startsWith('PMID:'))return 'https://pubmed.ncbi.nlm.nih.gov/'+encodeURIComponent(ref.slice(5))+'/';if(ref.startsWith('DOI:'))return 'https://doi.org/'+ref.slice(4);if(ref.startsWith('GO_REF:'))return 'https://geneontology.org/GO_REF/'+encodeURIComponent(ref.slice(7))+'.html';if(ref.startsWith('Reactome:'))return 'https://reactome.org/content/detail/'+encodeURIComponent(ref.slice(9));return null;}
function showGO(id,goid){const m=A().maps().marker.get(id);if(!m)return;const all=values(m,'go').filter(g=>g.id===goid),matching=goRows(m).filter(g=>g.id===goid);showDialog(`<h2 id="mw-dialog-title">${E(m.symbol)} <span>/ ${E(goid)}</span></h2><p class="mw-dialog-boundary">${T('goCodeHelp')}</p>${all.map(g=>`<article class="mw-evidence-relation"><div class="mw-relation-heading"><span class="mw-evidence-grade">${E(g.evidenceCode)}</span><strong>${E(g.term)}</strong>${matching.includes(g)?`<small>${T('matching')}</small>`:''}</div><dl><dt>${T('goAspect')}</dt><dd>${E(g.aspect)}</dd><dt>${T('relation')}</dt><dd>${E(g.relation)}</dd><dt>${T('assignedBy')}</dt><dd>${E(g.assignedBy||'—')}</dd></dl><div class="mw-reference-links"><a href="https://amigo.geneontology.org/amigo/term/${encodeURIComponent(goid)}" target="_blank" rel="noopener noreferrer">${E(goid)} ${icon('external')}</a>${(g.references||[]).map(ref=>referenceUrl(ref)?`<a href="${E(referenceUrl(ref))}" target="_blank" rel="noopener noreferrer">${E(ref)} ${icon('external')}</a>`:`<span>${E(ref)}</span>`).join('')}</div></article>`).join('')}<div class="mw-dialog-actions">${button('edit',`${icon('plus')}${T('edit')}`,`data-id="${E(id)}"`,'mw-button mw-primary')}</div>`);}
