function exportData(){const p=P();return {schema:'yeastvar-marker-panel-v1',exported:new Date().toISOString(),catalogUpdated:data().updated,kind:'research-plan-not-observed-cell-labels',markers:p.markers,records:p.markers.map(a=>({assignment:a,reference:cleanRecord(A().maps().marker.get(a.id))})),review:review(p),candidateQuery:{filters:filterSnapshot(),combinedScope:ui.resultSet},sources:data().sources.filter(s=>p.markers.some(a=>values(A().maps().marker.get(a.id),'evidence').some(e=>e.sourceId===s.id||e.extractionSourceId===s.id)||values(A().maps().marker.get(a.id),'referenceMeasurements').some(r=>r.sourceId===s.id)))};}
function resolveInput(input){const lookup=new Map();const add=(key,id)=>{if(!key)return;key=String(key).trim().toUpperCase();lookup.set(key,[...new Set([...(lookup.get(key)||[]),id])])};records().forEach(m=>{[m.id,m.symbol,m.systematic,...values(m,'aliases')].forEach(v=>add(v,m.id))});let items;if(typeof input==='string'){const raw=input.trim();if(raw.startsWith('{')||raw.startsWith('[')){const parsed=JSON.parse(raw);if(Array.isArray(parsed))items=parsed;else if(['yeastvar-marker-panel-v1','yeastvar1011-plan-v2'].includes(parsed.schema)&&Array.isArray(parsed.markers))items=parsed.markers;else throw Error('schema');}else items=raw.split(/[\s,;]+/).filter(Boolean);}else items=input;const rows=[],unresolved=[],seen=new Set();let duplicate=0;for(const x of items){const key=typeof x==='string'?x:x.id||x.symbol||x.systematic||'',found=lookup.get(String(key).trim().toUpperCase());if(found?.length===1){if(seen.has(found[0]))duplicate++;else {seen.add(found[0]);rows.push(typeof x==='object'?{...x,id:found[0]}:{id:found[0]});}}else unresolved.push(String(key).slice(0,200));}return {rows,unresolved,duplicate};}
function importData(input,{apply=false}={}){const resolved=resolveInput(input);if(apply){B().setMarkers(resolved.rows.map(x=>x.id),true,false);for(const a of resolved.rows){const patch={};for(const key of ['groups','purpose','purposes','role','userTags','rationale','evidenceSources'])if(Object.hasOwn(a,key))patch[key]=a[key];if(Object.keys(patch).length)B().updateMarker(a.id,patch,false);}}return resolved;}
function exportTSV(){const citations=window.YV_CITATIONS?.build(exportData());const safe=v=>{const s=String(v??'').replace(/[\r\n\t]/g,' ');return /^[=+@-]/.test(s)?"'"+s:s};const fields=['symbol','systematic','sgd_id','role','planned_groups','planned_uses','custom_tags','rationale','selected_evidence_sources','source_phase_labels','all_evidence_sources','project_mean','project_detection','project_rank','project_specificity','citation_apa7'];const rows=P().markers.map(a=>{const m=A().maps().marker.get(a.id);return [m.symbol,m.systematic,a.id,a.role||'include',(a.groups||[]).join(';'),(a.purposes||[a.purpose]).join(';'),(a.userTags||[]).join(';'),a.rationale||'',(a.evidenceSources||[]).join(';'),values(m,'phases').join(';'),[...new Set(values(m,'evidence').map(e=>e.sourceId))].join(';'),m.expression?.mean??'',m.expression?.detection??'',m.expression?.rank??'',m.expression?.specificity??'',citations?.cite(values(m,'evidence').map(e=>e.sourceUrl),{html:false})||''].map(safe).join('\t')});A().download('yeastvar1011-marker-panel.tsv','\uFEFF'+[fields.join('\t'),...rows].join('\n'),'text/tab-separated-values;charset=utf-8');}
function editMarker(id){B().setMarkers([id],true,false);ui.tab='panel';ui.panelQ='';ui.panelGroup='all';ui.edit=id;ui.panelPage=Math.floor(P().markers.findIndex(a=>a.id===id)/ui.size)+1;dialogClose();if(A().route()!=='markers')location.hash='markers';else refresh();requestAnimationFrame(()=>document.querySelector(`[data-mw-editor="${id}"]`)?.scrollIntoView({block:'nearest',behavior:A().prefs().reducedMotion?'auto':'smooth'}));}
document.addEventListener('click',event=>{const el=event.target.closest('[data-mw]');if(!el||!A())return;const act=el.dataset.mw,id=el.dataset.id;switch(act){case'mobile-filters':ui.mobileFilters=!ui.mobileFilters;refresh();if(!ui.mobileFilters)document.querySelector('.mw-mobile-filter-toggle')?.focus({preventScroll:true});break;case'clear-filter':ui[el.dataset.key]=el.dataset.key==='selectedOnly'?false:'';ui.page=1;refresh();break;case'clear-panel-filters':ui.panelQ='';ui.panelGroup='all';ui.panelPage=1;refresh();break;case'review-selected':ui.tab='panel';ui.panelQ='';ui.panelGroup='all';ui.panelPage=1;refresh();document.querySelector('.mw-tabs')?.scrollIntoView({block:'start'});break;case'discard-draft':drafts.delete(id);persistDrafts();refresh();break;case'tab':ui.tab=el.dataset.value;refresh();break;case'reset':resetFilters();refresh();break;case'search-all':resetFilters(true);refresh();break;case'evidence-kind':ui.evidenceKind=el.dataset.value;ui.evidenceBranch='all';ui.goTerms=[];ui.goCodes=[];ui.goQ='';ui.goPage=1;ui.phases=[];ui.page=1;refresh();break;case'exclude-tag':{const tag=el.dataset.value;ui.excludedTags=ui.excludedTags.includes(tag)?ui.excludedTags.filter(t=>t!==tag):[...ui.excludedTags,tag];ui.tags=ui.tags.filter(t=>t!==tag);ui.page=1;refresh();break;}case'go-page':ui.goPage=Number(el.dataset.value);refresh();break;case'capture-set':ui.setA={ids:resultRows().map(m=>m.id),filters:filterSnapshot()};refresh();break;case'combine-set':combineSet(el.dataset.value);break;case'clear-set':ui.setA=null;refresh();break;case'clear-scope':ui.resultSet=null;ui.page=1;refresh();break;case'phase-source':resetFilters();ui.evidenceKind='rna';ui.evidenceBranch='phaseRNA';ui.phases=[el.dataset.value];ui.sources=[el.dataset.source];ui.open.add('phase');refresh();document.querySelector('.mw-catalogue')?.scrollIntoView({block:'start',behavior:A().prefs().reducedMotion?'auto':'smooth'});break;case'tag-mode':ui.tagMode=el.dataset.value;ui.page=1;refresh();break;case'remove-filter':ui[el.dataset.key]=ui[el.dataset.key].filter(v=>v!==el.dataset.value);ui.page=1;refresh();break;case'page':ui.page=Number(el.dataset.value);refresh();document.querySelector('.mw-results')?.scrollIntoView({block:'start'});break;case'panel-page':ui.panelPage=Number(el.dataset.value);refresh();break;case'select':if(member(id)){drafts.delete(id);persistDrafts();}B().setMarkers([id],!member(id),false);refresh();break;case'remove':drafts.delete(id);persistDrafts();B().setMarkers([id],false,false);ui.checked.delete(id);refresh();break;case'add-page':B().setMarkers(resultRows().slice((ui.page-1)*ui.size,ui.page*ui.size).map(m=>m.id),true,false);refresh();break;case'edit':editMarker(id);break;case'close-edit':ui.edit=null;refresh();break;case'evidence':showEvidence(id,el.dataset.tag);break;case'reference-stats':showReferenceMeasurements(id);break;case'go-evidence':showGO(id,el.dataset.go);break;case'all-tags':showAllTags(id);break;case'close-dialog':dialogClose();break;case'full-record':dialogClose();A().openRecord('marker',id);break;case'export':A().download('yeastvar1011-marker-panel.json',JSON.stringify(exportData(),null,2));break;case'export-tsv':exportTSV();break;case'source-filter':ui.tab='catalogue';ui.sources=[el.dataset.value];ui.page=1;refresh();document.querySelector('.mw-workspace')?.scrollIntoView({block:'start'});break;case'batch-role':B().updateMarkers([...ui.checked],{role:document.getElementById('mw-batch-role').value},false);refresh();break;case'clear-checked':ui.checked.clear();refresh();break;case'resolve':try{ui.importText=document.getElementById('mw-import-text').value;ui.resolved=resolveInput(ui.importText);refresh();}catch{A().toast(T('badFile'))}break;case'apply-import':if(ui.resolved){importData(ui.resolved.rows,{apply:true});ui.tab='panel';refresh();A().toast(T('saved'))}break;}});
document.addEventListener('change',async event=>{const el=event.target;if(el.dataset.mwFilter){const key=el.dataset.mwFilter;ui[key]=el.checked?[...new Set([...ui[key],el.value])]:ui[key].filter(v=>v!==el.value);if(key==='tags'&&el.checked)ui.excludedTags=ui.excludedTags.filter(t=>t!==el.value);ui.page=1;refresh();}else if(el.hasAttribute('data-mw-selected-only')){ui.selectedOnly=el.checked;ui.page=1;refresh();}else if(el.dataset.mwValue){ui[el.dataset.mwValue]=el.value;if(el.dataset.mwValue==='evidenceBranch'){ui.goTerms=[];ui.goCodes=[];ui.goQ='';ui.goPage=1;if(!['all','phaseRNA','singlecellRNA'].includes(el.value))ui.phases=[];}ui.page=1;ui.panelPage=1;refresh();}else if(el.dataset.mwChecked){el.checked?ui.checked.add(el.dataset.mwChecked):ui.checked.delete(el.dataset.mwChecked);refresh();}else if(el.id==='mw-check-page'){panelRows().slice((ui.panelPage-1)*ui.size,ui.panelPage*ui.size).forEach(a=>el.checked?ui.checked.add(a.id):ui.checked.delete(a.id));refresh();}else if(el.id==='mw-import-file'){try{const file=el.files?.[0];if(!file)return;if(file.size>20e6)throw Error('size');ui.importText=await file.text();ui.resolved=resolveInput(ui.importText);refresh();}catch{A().toast(T('badFile'))}}});
document.addEventListener('input',event=>{const map={'mw-query':'q','mw-tag-query':'tagQ','mw-panel-query':'panelQ','mw-go-query':'goQ'},key=map[event.target.id];if(key){ui[key]=event.target.value;ui.page=1;ui.panelPage=1;ui.goPage=1;clearTimeout(searchTimer);const id=event.target.id;searchTimer=setTimeout(()=>refresh(id),200)}else if(event.target.id==='mw-import-text')ui.importText=event.target.value});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-mw-editor]');if(!form)return;event.preventDefault();const patch=readEditor(form);drafts.delete(form.dataset.mwEditor);persistDrafts();B().updateMarker(form.dataset.mwEditor,patch,false);refresh();A().toast(T('saved'));});
